// ============ COLLEZ VOS CLES ICI — C'EST TOUT ============
// Les modeles sont des NOEUDS VISIBLES a droite. Ici vous ne mettez que les cles.
// (Ces cles restent dans votre instance n8n ; n'exportez pas ce workflow avec elles.)

const CLES = {
  // Une cle restee a "COLLER_..." est detectee au lancement pour tout
  // modele actif : la campagne s'arrete au lieu d'echouer 126 fois.
  anthropic:  "COLLER_CLE_ANTHROPIC",   // console.anthropic.com
  openai:     "COLLER_CLE_OPENAI",      // platform.openai.com
  google:     "COLLER_CLE_GEMINI",    // aistudio.google.com — METHODE B uniquement
  // agregateur: plus utilise — les open-weight passent desormais en direct
  agregateur: "COLLER_CLE_AGREGATEUR",  // conserve au cas ou
  deepseek:   "COLLER_CLE_DEEPSEEK",    // platform.deepseek.com
  qwen:       "COLLER_CLE_QWEN",        // Alibaba Cloud Model Studio (DashScope)
  kimi:       "COLLER_CLE_KIMI",        // platform.moonshot.ai
};

// DEFINIR LA RACINE (pour récupérer les échantillons)

// SOit la garder vide et lancer n8n avec 
// cd "%USERPROFILE%"
// npx n8n

// Soit la laisser avec les valeurs actuelles : 
  const RACINE_MANUELLE = "C:/Users/<nom_du_user>/.n8n-files";            // 
const RACINE_RELATIVE = ".n8n-files";  // repli sans variable d'environnement

// Correction d'erreur d'accès à l'environnement USERPROFILE. 
function env(n) {
  try {
    const v = ($env && $env[n]) ? String($env[n]) : "";
    return /access to env vars denied|\[ERROR/i.test(v) ? "" : v;
  } catch (e) { return ""; }
}
const profil = env("USERPROFILE") || (env("HOMEDRIVE") + env("HOMEPATH"))
               || env("HOME");
let racine_source = "RACINE_MANUELLE";
let racine = RACINE_MANUELLE;
if (!racine) { racine = env("N8N_FILES_DIR"); racine_source = "N8N_FILES_DIR"; }
if (!racine && profil) { racine = profil + "/.n8n-files"; racine_source = "profil utilisateur"; }
if (!racine) { racine = RACINE_RELATIVE; racine_source = "chemin relatif au dossier de lancement de n8n"; }
racine = racine.replace(/\\/g, "/").replace(/\/+$/, "");

// ============ QUEL(S) MODELE(S) CETTE EXECUTION TRAITE ============
// "" (DEFAUT) = ce sont les cases actif:true de « Preparer les iterations »
//              qui decident ; plusieurs modeles actifs tournent en serie.
// Non vide   = force CE modele et IGNORE les cases actif. Il doit alors etre
//              marque actif:true, sinon la campagne s'arrete : une valeur
//              oubliee ici relancerait un modele deja evalue et ajouterait ses
//              lignes en double dans son fichier de resultats.
// Pour lancer N campagnes en parallele : dupliquer ce workflow N fois dans n8n
// et ne changer QUE cette ligne dans chaque copie. Chaque execution ecrira dans
// son propre fichier, donc aucune collision sur l'ecriture en mode ajout.
// La valeur doit correspondre exactement au champ "modele" de la liste MODELES.
const MODELE_FORCE = "";

// ============ PROJET GCP FACTURE POUR LE QUOTA VERTEX ============

const PROJET_GCP = "id_projet_vertex_google";   // <- verifier dans la console GCP

// Endpoint open-weight (choisir UNE ligne) :
const AGG_BASE = "https://api.deepinfra.com/v1/openai";   // DeepInfra
// const AGG_BASE = "https://openrouter.ai/api/v1";       // OpenRouter

return [{ json: {
  CLES, AGG_BASE, racine, modele_force: MODELE_FORCE,
  runs_par_question: 3,     // 3 - 5 executions par echantillon (stabilite) chosir un nombre pair pour éviter un cas ambigu 
  limite_samples: 0,        // 0 = LES 42 echantillons ; mettre 4-5 pour un test de cout
  numero_run_depart: 1,
  temperature: 0,
  // Plafond de sortie IDENTIQUE pour tous les modeles. 32768 est assez haut
  // pour qu'aucun modele ne l'atteigne sur cette tache (Gemini a produit au
  // maximum 426 jetons, soit 1,3 % du plafond) tout en gardant un filet de
  // securite contre une generation qui s'emballe : a 15 $/M en sortie chez
  // Moonshot, 131 000 jetons couteraient 2 $ pour un seul appel.
  // Le champ meta.fin_raison permet de PROUVER apres coup qu'il n'a jamais
  // contraint personne : aucun enregistrement ne doit porter "length".
  // Ne PAS supprimer ce parametre : il est obligatoire chez Anthropic.
  max_tokens_sortie: 32768,
  // --- espacement nominal entre deux appels reussis ---
  pause_entre_appels_s: 8,  // pause PAR DEFAUT ; surchargee par modele via pause_apres_s (Moonshot direct : 21 s car 3 req/min).

  // --- reprise sur erreur transitoire (429 / 5xx / reseau) ---
  // Vertex renvoie 429 quand la capacite partagee (Dynamic Shared Quota) est
  // saturee : ce n'est PAS une question de cadence, c'est une question de
  // disponibilite. On respecte le Retry-After / retryDelay du serveur, sinon
  // backoff exponentiel avec jitter.
  // Timeout client. Vertex coupe de lui-meme a 10 min ; un timeout plus court
  // fait apparaitre des 499 (CANCELLED) cote Google : la requete a consomme de
  // la capacite mais ne rend rien. 180 s etait trop court pour un modele a
  // raisonnement avec max_tokens_sortie a 8192.
  timeout_appel_ms: 600000,

  max_tentatives: 5,        // remonte de 2 : au palier 3 req/min de Moonshot, un
                            // seul reessai ne suffit pas a absorber une rafale de 429
  backoff_base_s: 25,   // repli si AUCUN delai serveur ; compatible palier 3 RPM Moonshot.       // 15 -> 30 -> 60 -> 60 ... (avec jitter)
  backoff_max_s: 60,        // < 65 s : n8n garde l'execution en memoire au lieu de la decharger en base

  gcp_project_id: env("GCP_PROJECT_ID") || PROJET_GCP,
  fichier_adc:     racine + "/application_default_credentials.json",
  fichier_dataset: racine + "/dataset/S*.jsonl",
  // ---- sortie : UN FICHIER PAR MODELE ----
  // Le nom complet est construit dans "Preparer les iterations" a partir de
  // l'identifiant du modele. Indispensable des lors que plusieurs campagnes
  // tournent en parallele : le noeud d'ecriture est en mode ajout, et deux
  // executions visant le meme fichier entrelaceraient leurs lignes.
  dossier_sortie:  racine + "/resultats",
  suffixe_sortie:  "",      // ex. "_essai2" pour ne pas melanger deux campagnes

  prompt_system: "Tu es un analyste en cybersecurite specialiste du referentiel MITRE ATT&CK (matrices Enterprise et ICS). On te soumet les journaux produits par UNE SEULE action offensive. Ta mission : produire le mapping ATT&CK aux trois niveaux.\n\nREPONDS UNIQUEMENT par un objet JSON valide, sans texte avant ni apres, sans balises Markdown, au schema EXACT suivant :\n{\n  \"tactique\": \"TAxxxx\",\n  \"technique\": \"Txxxx\",\n  \"sous_technique\": \"Txxxx.yyy\",\n  \"element_cite\": \"l'element du journal qui justifie le mapping\",\n  \"justification\": \"une ou deux phrases\"\n}\n\nRegles imperatives :\n- UN SEUL identifiant par niveau. Jamais de liste, jamais d'alternative, jamais de \"ou\". Toute reponse contenant plusieurs identifiants a un meme niveau est rejetee.\n- \"technique\" est la technique PARENTE, sans suffixe (ex. \"T1059\", pas \"T1059.001\").\n- \"sous_technique\" : l'identifiant complet (ex. \"T1059.001\") si la technique en possede une qui correspond ; exactement la chaine \"aucune\" si la technique n'en possede pas ; la chaine vide \"\" si tu ne peux pas determiner laquelle.\n- Laisse de meme la chaine vide \"\" a un niveau que tu ne peux pas determiner. Ne devine pas pour remplir.\n- N'invente aucun identifiant : uniquement des identifiants MITRE ATT&CK reels, de la matrice indiquee dans la question.\n- \"element_cite\" : recopie l'element PRECIS du journal utilise comme preuve.",
  // ================= PHASE 2 : SERVEUR MCP MITRE ATT&CK =================
  mcp_actif: true,          // false = rejoue exactement la campagne de phase 1

  // Le serveur tourne en local : uv run mcp_mitre.py --http
  // Il n'a AUCUNE authentification : le laisser sur la boucle locale.
  // Depuis n8n en conteneur Docker, remplacer 127.0.0.1 par
  // host.docker.internal (Windows/macOS) ou par l'IP de la passerelle.
  mcp_url: "http://127.0.0.1:8733/mcp",
  mcp_sonde: "http://127.0.0.1:8733/healthz",
  mcp_timeout_ms: 120000,

  // Version du serveur MCP exigee pour cette campagne ("" = pas de controle).
  // Tous les modeles compares doivent etre servis par la MEME version : le
  // bloc d'outils que lit le modele (tools/list) en depend. La v2.2.2 rend
  // les memes reponses ATT&CK que la v2.2.1, mais les descriptions de trois
  // outils internes different. La campagne s'arrete si la sonde /healthz
  // annonce une autre version.
  mcp_version_attendue: "2.2.2",

  // Nombre maximal d'allers-retours d'outils pour UNE iteration. Au-dela,
  // l'iteration est close en 'mcp_tours_epuises' et exclue des metriques :
  // une boucle d'outils qui ne converge pas ne mesure pas la competence de
  // mapping du modele. 8 laisse la place a recherche -> verification ->
  // controle de la parente -> tactiques, avec de la marge.
  mcp_max_tours: 8,

  // ---- PERIMETRE D'OUTILS : le modele choisit, on ne choisit pas pour lui --
  // Le serveur expose dix-huit outils et le modele les decouvre par
  // `tools/list` ; c'est lui qui decide lesquels appeler et dans quel ordre.
  // La SELECTION D'OUTIL fait partie de ce que la campagne mesure : restreindre
  // le perimetre aux seuls outils porteurs d'identifiants rendrait le taux
  // d'appels pertinents de calculer_metriques.py egal a 100 % par construction,
  // et cette metrique n'a de sens que si le modele peut appeler autre chose.
  // Le surcout du bloc de descriptions, relu a chaque tour (environ 2 280
  // jetons pour dix-sept outils contre 840 pour quatre), est MESURE par le
  // compteur de jetons, pas suppose.
  //
  // Liste vide = tous les outils sauf ceux nommes dans mcp_outils_exclus.
  mcp_outils: [],

  // Une seule exclusion, et elle n'est pas un choix de perimetre : c'est un
  // garde-fou de campagne. `mitre_update` retelecharge les deux matrices et
  // remplace la base en memoire. Appele par le modele au milieu des 126
  // executions, il changerait la version ATT&CK servie en cours de campagne —
  // ce que le chapitre 1 interdit (referentiel fige) et que le compteur de
  // derive de version detecterait trop tard, les lignes deja ecrites etant
  // alors incomparables. Les dix-sept autres outils sont en lecture seule.
  mcp_outils_exclus: ["mitre_update"],

  // Chapitre 1, section 4.1 : « la phase 2 rejoue la campagne avec le serveur
  // MCP ». Le premier tour impose donc un appel d'outil (tool_choice: any),
  // les tours suivants rendent la main au modele (tool_choice: auto) pour
  // qu'il puisse conclure. Consequence a declarer : le « taux d'utilisation
  // MCP » devient 100 % par construction et cesse d'etre informatif ; ce sont
  // le taux d'appels pertinents et le taux de reponses ancrees qui portent
  // alors l'information. Mettre false pour laisser le modele libre.
  mcp_forcer_premier_appel: true,

  // Consigne AJOUTEE au prompt systeme quand le MCP est actif, et rien
  // d'autre : le prompt de phase 1 reste identique au caractere pres, il est
  // recopie tel quel dans chaque enregistrement pour que la difference soit
  // verifiable apres coup. Mettre "" pour un prompt strictement identique
  // (le modele decouvre alors les outils par le seul bloc `tools`).
  mcp_consigne: "\n\nTu disposes d'outils interroges sur une copie locale de MITRE ATT&CK 19.2. Ils font FOI : ne reponds pas de memoire quand un outil peut trancher. Methode attendue : search_techniques avec le parametre matrix correspondant a la matrice indiquee, puis get_technique sur chaque candidat retenu pour verifier la tactique et l'existence de la sous-technique. Le champ `homonymes` d'une reponse signale un nom present dans les deux matrices : lever l'ambiguite avec matrix avant de conclure. Un resultat portant `matched.pivot` est une piste, pas un mapping. Le format de ta reponse finale ne change pas : le meme objet JSON, seul, sans texte autour.",
  version_pipeline_mcp: "5.0-mcp",
  version_pipeline: "4.2-methodo"
}}];

const it = $input.first().json;
const f=it.fournisseur, base=it.base_url, cle=it.cle;
const model=it.modele, maxtok=it.max_tokens_sortie, temp=it.temperature;
const ps=it.prompt_system, pu=it.prompt_user;

const url = (f==='anthropic') ? base+'/v1/messages' : base+'/chat/completions';

// --- entetes construits ici : plus d'entete vide ni d'entete d'un autre
// --- fournisseur envoyee a Google (l'ancienne version poussait toujours
// --- anthropic-version et un x-goog-user-project vide).
const entetes = { 'Content-Type': 'application/json' };
if (f === 'anthropic') { entetes['x-api-key'] = cle; entetes['anthropic-version'] = '2023-06-01'; }
else { entetes['Authorization'] = 'Bearer ' + cle; }
if (f === 'vertex') {
  if (!it.gcp_project_id) throw new Error("gcp_project_id vide : le quota Vertex ne peut etre attribue a aucun projet.");
  entetes['x-goog-user-project'] = it.gcp_project_id;   // projet dont le quota est consomme
}

let corps, temp_appliquee = temp;
let etat_messages = null;
if (f === 'anthropic') {
  // PAS de temperature pour Claude. Sur les modeles 4.7 et suivants (dont
  // claude-opus-4-8 et claude-opus-5), le parametre est deprecie : seule sa
  // valeur par defaut est acceptee, meme reflexion desactivee. Et des que la
  // reflexion est active, la temperature doit valoir 1 ou rester absente.
  // Transmettre 0 fait echouer la requete.
  // Consequence methodologique : Claude n'est PAS evalue a temperature 0
  // comme les autres modeles. A declarer dans la methodologie ; c'est aussi
  // pourquoi sa variance entre les 3 executions sera plus elevee.
  temp_appliquee = null;
  const messages0 = [{role:'user', content:pu}];
  const corpsObj = {model, max_tokens:maxtok, system:ps, messages:messages0};
  // MCP : les outils sont declares ici, exactement tels que le serveur les
  // documente. `tool_choice: auto` laisse le modele libre de ne rien appeler,
  // ce qui est volontaire : forcer un appel biaiserait la mesure.
  const outils = (it.mcp_actif === true)
                 ? ($('Normaliser les outils MCP').first().json.outils_mcp || []) : [];
  if (it.mcp_actif === true && outils.length) {
    corpsObj.tools = outils;
    // `any` au premier tour : le modele DOIT consulter le referentiel avant de
    // repondre, ce qui est la condition meme de la phase 2. Les tours suivants
    // repassent en `auto` (voir « Integrer les resultats d'outils ») pour qu'il
    // puisse conclure des qu'il a ce qu'il lui faut.
    corpsObj.tool_choice = (it.mcp_forcer_premier_appel === true)
                           ? { type: 'any' } : { type: 'auto' };
  }
  corps = JSON.stringify(corpsObj);
  etat_messages = messages0;
}
else if (f==='openai') {
  // La temperature n'a jamais ete transmise a OpenAI ici : on le reflete
  // desormais honnetement dans temperature_appliquee au lieu d'y laisser 0.
  temp_appliquee = null;
  corps=JSON.stringify({model,max_completion_tokens:maxtok,messages:[{role:'system',content:ps},{role:'user',content:pu}]});
}
else {
  // Certains modeles a raisonnement (ex. kimi-k3 en direct) refusent toute
  // temperature autre que leur defaut -> on omet le champ (sans_temperature).
  const b = {model, max_tokens:maxtok,
             messages:[{role:'system',content:ps},{role:'user',content:pu}]};
  if (it.sans_temperature === true) temp_appliquee = null;
  else b.temperature = temp;
  corps=JSON.stringify(b);
}

return [{ json: { ...it, url, entetes: JSON.stringify(entetes), corps,
  temperature_appliquee: temp_appliquee,
  tentative: Number(it.tentative || 1),
  // etat de la boucle d'outils : remis a zero a chaque nouvelle tentative
  messages_etat: etat_messages, tour: 1, mcp_trace: [],
  mcp_appels: 0, mcp_ms: 0, mcp_erreurs: 0,
  usage_cumul: { entree: 0, sortie: 0 },
  horodatage_debut:new Date().toISOString(), t0_ms:Date.now() } }];

function noeud(nom) { try { return $(nom).first().json; } catch (e) { return null; } }
const prep0 = noeud("Preparer l'appel") || {};
const suite = noeud("Integrer les resultats d'outils");
// run_id : sans ce garde-fou, une iteration sans appel d'outil heriterait de
// la trace MCP de l'iteration precedente, restee en memoire dans le noeud.
const prep = (suite && suite.run_id === prep0.run_id)
             ? { ...prep0, ...suite } : prep0;
const cfg  = $('Configuration').first().json;
const brut = $input.first().json || {};
const horodatage_fin = new Date().toISOString();
const latence_ms = Date.now() - prep.t0_ms;
const tentative = Number(prep.tentative || 1);
const max_tentatives = Number(cfg.max_tentatives || 8);

// --- le noeud HTTP est en fullResponse + neverError : on a le code, les entetes
// --- et le corps meme en cas d'erreur. Seules les pannes transport levent encore.
const panne_transport = brut.error !== undefined && brut.statusCode === undefined;
const code = panne_transport ? null : Number(brut.statusCode);
const rep  = panne_transport ? {} : (brut.body !== undefined ? brut.body : brut);
const entetes_rep = brut.headers || {};

let erreur_api = null;
if (panne_transport) {
  const er = brut.error || {};
  erreur_api = 'transport - ' + (er.description || er.message || JSON.stringify(er)).toString().slice(0, 300);
} else if (code >= 400) {
  const e = (rep && rep.error) || {};
  erreur_api = code + ' - ' + String(e.message || e.status || JSON.stringify(rep)).slice(0, 300);
}

// --- combien de temps le serveur nous demande-t-il d'attendre ? ---
let delai_serveur_s = null;
const ra = entetes_rep['retry-after'] || entetes_rep['Retry-After'];
if (ra && /^\d+$/.test(String(ra).trim())) delai_serveur_s = Number(String(ra).trim());
if (delai_serveur_s === null) {
  const m = JSON.stringify(rep || {}).match(/"retryDelay"\s*:\s*"(\d+(?:\.\d+)?)s"/);
  if (m) delai_serveur_s = Math.ceil(Number(m[1]));
}
// Moonshot n'envoie NI Retry-After NI retryDelay : le delai est dans le TEXTE
// du message ("please try again after N seconds").
if (delai_serveur_s === null && erreur_api) {
  const m2 = erreur_api.match(/try again after (\d+(?:\.\d+)?) seconds?/i);
  if (m2) delai_serveur_s = Math.max(1, Math.ceil(Number(m2[1])));
}

// --- erreur transitoire ? (429 quota, 5xx, timeout, coupure reseau) ---
const txt_err = (erreur_api || '').toLowerCase();
// 499 = CANCELLED : connexion fermee avant la reponse (timeout client) ou
// annulation cote Google en charge. Transitoire dans les deux cas.
// 504 = DEADLINE_EXCEEDED. Ni l'un ni l'autre n'est une erreur du modele.
const transitoire = code === 429 || code === 408 || code === 409 || code === 499 || (code >= 500)
  || (panne_transport && /etimedout|econnaborted|econnreset|econnrefused|eai_again|und_err|socket hang up|aborted|timeout|deadline|network/i.test(txt_err));
const a_reessayer = transitoire && tentative < max_tentatives;

let texte=null, tin=null, tout=null, fin_raison=null, tokens_raisonnement=null;
if (prep.fournisseur === 'anthropic') {
  texte = Array.isArray(rep.content) ? (rep.content.find(c=>c.type==='text')||{}).text : null;
  tin = rep.usage ? rep.usage.input_tokens : null; tout = rep.usage ? rep.usage.output_tokens : null;
  fin_raison = rep.stop_reason || null;
} else {
  const ch = (rep.choices && rep.choices[0]) ? rep.choices[0] : {};
  texte = ch.message ? ch.message.content : null;
  tin = rep.usage ? rep.usage.prompt_tokens : null; tout = rep.usage ? rep.usage.completion_tokens : null;
  fin_raison = ch.finish_reason || ch.native_finish_reason || null;
  const det = rep.usage && rep.usage.completion_tokens_details;
  if (det && det.reasoning_tokens !== undefined && det.reasoning_tokens !== null) {
    tokens_raisonnement = Number(det.reasoning_tokens);
  }
}
// Troncature : max_tokens epuise (souvent par le raisonnement) avant la fin du
// JSON. C'est un echec de BUDGET, pas du modele -> statut dedie, a exclure des
// metriques au meme titre que les erreurs d'infrastructure.
const tronque = fin_raison === 'length' || fin_raison === 'max_tokens';

// --- normalisation d'un niveau : UNE seule valeur, sinon format non respecte ---
const RE_ID = /(?:TA\d{4}|T\d{4}(?:\.\d{3})?)/gi;
let format_ok = true;
function niveau(v) {
  if (v === null || v === undefined) return "";
  if (Array.isArray(v)) {
    if (v.length === 0) return "";
    if (v.length > 1) { format_ok = false; return String(v[0]).trim().toUpperCase(); }
    v = v[0];
  }
  let s = String(v).trim();
  if (!s) return "";
  if (/^(aucune|aucun|none|n\/a|null)$/i.test(s)) return "aucune";
  const ids = s.match(RE_ID);
  if (!ids) { format_ok = false; return s.toUpperCase(); }
  if (ids.length > 1) { format_ok = false; }
  return ids[0].toUpperCase();
}

let mapping = { tactique:"", technique:"", sous_technique:"" };
let element_cite=null, justification=null, statut='ok';
if (erreur_api) {
  if (code === 429) statut = 'erreur_quota_429';
  else if (code === 499) statut = 'erreur_annulee_499';
  else if (code === 504) statut = 'erreur_deadline_504';
  else if (panne_transport) statut = /timeout|econnaborted|deadline|aborted/i.test(txt_err)
                                     ? 'erreur_timeout' : 'erreur_reseau';
  else statut = 'erreur_api';
  // une erreur transitoire epuisee n'est PAS une erreur du modele : on la marque
  // pour pouvoir l'exclure du calcul des metriques et la rejouer.
  if (transitoire && !a_reessayer) statut += '_abandon';
}
else if (brut.mcp_tours_epuises === true) {
  // La boucle d'outils n'a pas converge dans le budget de tours : ce n'est
  // pas une erreur de mapping, l'iteration est exclue des metriques.
  statut = 'mcp_tours_epuises';
}
else if (!texte) statut = tronque ? 'troncature_budget' : 'reponse_vide';
else {
  let t=texte.trim();
  const m=t.match(/```(?:json)?\s*([\s\S]*?)```/); if(m) t=m[1].trim();
  const d=t.indexOf('{'), e=t.lastIndexOf('}'); if(d>=0&&e>d) t=t.slice(d,e+1);
  try {
    const p=JSON.parse(t);
    mapping = { tactique: niveau(p.tactique !== undefined ? p.tactique : p.tactiques),
                technique: niveau(p.technique !== undefined ? p.technique : p.techniques),
                sous_technique: niveau(p.sous_technique !== undefined ? p.sous_technique : p.sous_techniques) };
    element_cite = typeof p.element_cite === 'string' ? p.element_cite
                 : (Array.isArray(p.elements_cites) ? p.elements_cites.join(' | ') : null);
    justification = typeof p.justification === 'string' ? p.justification : null;
    if (mapping.tactique && !/^TA\d{4}$/.test(mapping.tactique)) format_ok = false;
    if (mapping.technique && !/^T\d{4}$/.test(mapping.technique)) format_ok = false;
    if (mapping.sous_technique && mapping.sous_technique !== 'aucune'
        && !/^T\d{4}\.\d{3}$/.test(mapping.sous_technique)) format_ok = false;
    if (!format_ok) statut = 'format_non_respecte';
  } catch(e2) { statut = tronque ? 'troncature_budget' : 'json_invalide'; }
}
if (statut !== 'ok') mapping = { tactique:"", technique:"", sous_technique:"" };
if (statut === 'mcp_tours_epuises') { /* exclu plus bas des metriques */ }

const enregistrement = {
  meta: { campagne:prep.campagne, version_pipeline:prep.version_pipeline,
          run_id:prep.run_id, modele:prep.modele, fournisseur:prep.fournisseur,
          log_id:prep.log_id, zone:prep.zone, source:prep.source, matrice:prep.matrice,
          numero_run:prep.numero_run, mcp_actif:prep.mcp_actif,
          temperature_appliquee: prep.temperature_appliquee === undefined
                                 ? null : prep.temperature_appliquee,
          horodatage_debut:prep.horodatage_debut, horodatage_fin, latence_ms,
          statut, erreur_api, code_http: code, fin_raison, tentative,
          erreur_infrastructure: transitoire && !a_reessayer,
          // --- trace MCP : tout ce qu'il faut pour expliquer un ecart avec
          // --- la campagne de phase 1 sans rejouer la campagne.
          mcp: prep.mcp_actif === true ? {
            serveur: prep.mcp_serveur || null,
            outils_exposes: prep.mcp_outils_exposes || [],
            tours: Number(prep.tour || 1),
            tours_epuises: brut.mcp_tours_epuises === true,
            appels_outils: Number(prep.mcp_appels || 0),
            appels_en_erreur: Number(prep.mcp_erreurs || 0),
            latence_mcp_ms: Number(prep.mcp_ms || 0),
            outils_appeles: (prep.mcp_trace || []).map(t => t.outil),
            matrices_demandees: (prep.mcp_trace || [])
              .filter(t => t.outil === 'search_techniques' || t.outil === 'get_datasources')
              .map(t => t.matrix),
            avertissements: Array.from(new Set(
              (prep.mcp_trace || []).reduce((a, t) => a.concat(t.avert || []), []))),
            forcer_premier_appel: prep.mcp_forcer_premier_appel === true,
            ids_vus: Array.from(new Set((prep.mcp_trace || [])
              .reduce((a, t) => a.concat(t.ids_retournes || []), []))).slice(0, 200),
          } : null,
          prompt_system_mcp: prep.prompt_system_mcp || "",
          // vrai des que l'iteration ne mesure PAS la competence du modele :
          // panne d'infrastructure abandonnee OU budget de sortie epuise.
          // calculer_metriques.py compte sinon ces cas en faux negatifs.
          exclure_des_metriques: (transitoire && !a_reessayer) || tronque
                                 || brut.mcp_tours_epuises === true },
  mapping, element_cite, justification,
  // ---- champs RACINE lus par calculer_metriques.py (section « serveur MCP »).
  // `appels_mcp` porte un objet par appel d'outil, dans l'ordre chronologique :
  //   outil / arguments / ok / inconnu / ids_retournes, plus tour, matrix et
  //   avert, additifs et ignores par le script d'origine.
  // `tours` compte les allers-retours ; `db_version_mcp` permet au script de
  //   detecter une derive entre le referentiel servi et la version figee.
  appels_mcp: prep.mcp_actif === true ? (prep.mcp_trace || []) : [],
  tours: Number(prep.tour || 1),
  db_version_mcp: prep.mcp_actif === true
                  ? ((prep.mcp_serveur || {}).db_version || null) : null,
  // Avec la boucle d'outils, l'appel HTTP final ne porte que le DERNIER tour.
  // Les jetons factures sont la somme de tous les tours : c'est ce total qui
  // doit etre compare au cout de la campagne sans MCP.
  usage: { tokens_entree: (Number((prep.usage_cumul||{}).entree || 0) + Number(tin || 0)) || tin,
           tokens_sortie: (Number((prep.usage_cumul||{}).sortie || 0) + Number(tout || 0)) || tout,
           tokens_raisonnement,
           tokens_entree_dernier_tour: tin, tokens_sortie_dernier_tour: tout },
  reponse_brute: texte ? texte.slice(0,4000) : null
};

// on n'accumule la statistique que pour les enregistrements DEFINITIFS
if (!a_reessayer) {
  const sd = $getWorkflowStaticData('global');
  sd.stats = sd.stats || [];
  sd.stats.push({ modele: prep.modele, log_id: prep.log_id, statut, latence_ms,
                  tentative, jetons: (tin||0) + (tout||0) });
}

return [{ json: { enregistrement, fichier_sortie: prep.fichier_sortie,
                  a_reessayer, tentative, delai_serveur_s } }];

// L'ancienne version lisait $('Assembler l'enregistrement').all(), qui ne renvoie
// que la DERNIERE execution du noeud : la synthese ne portait que sur 1 iteration.
// On accumule desormais au fil de la boucle (repli sur .all() si la static data
// n'est pas disponible).
const cfg = $('Configuration').first().json;
const sd  = $getWorkflowStaticData('global');
let stats = Array.isArray(sd.stats) ? sd.stats : [];
if (!stats.length) {
  try {
    stats = $('Assembler l\'enregistrement').all()
      .map(x => x.json.enregistrement).filter(Boolean)
      .map(e => ({ modele:e.meta.modele, log_id:e.meta.log_id, statut:e.meta.statut,
                   latence_ms:e.meta.latence_ms, tentative:e.meta.tentative || 1,
                   jetons:(e.usage.tokens_entree||0)+(e.usage.tokens_sortie||0) }));
  } catch(e) { stats = []; }
}

const parModele = {};
for (const s of stats) {
  const p = parModele[s.modele] = parModele[s.modele] ||
    { iterations:0, ok:0, format_non_respecte:0, abandons_infrastructure:0,
      autres_statuts:{}, tentatives_totales:0,
      latence_ms_moyenne:0, jetons_moyens:0, _lat:0, _jet:0 };
  p.iterations++;
  p.tentatives_totales += s.tentative || 1;
  if (s.statut === 'ok') p.ok++;
  else if (s.statut === 'format_non_respecte') p.format_non_respecte++;
  else if (/_abandon$/.test(s.statut)) p.abandons_infrastructure++;
  else p.autres_statuts[s.statut] = (p.autres_statuts[s.statut] || 0) + 1;
  p._lat += s.latence_ms || 0;
  p._jet += s.jetons || 0;
}
for (const m in parModele) {
  const p = parModele[m];
  p.latence_ms_moyenne = Math.round(p._lat / Math.max(p.iterations, 1));
  p.jetons_moyens      = Math.round(p._jet / Math.max(p.iterations, 1));
  delete p._lat; delete p._jet;
}

const echantillons = new Set(stats.map(s => s.log_id));
const abandons = stats.filter(s => /_abandon$/.test(s.statut)).length;

// on vide le cache pour que la campagne suivante reparte propre
sd.stats = []; delete sd.jeton_gcp; delete sd.jeton_expire_ms;

return [{ json: {
  campagne_terminee: true,
  total_iterations: stats.length,
  echantillons_couverts: echantillons.size,
  runs_par_echantillon: cfg.runs_par_question,
  mcp_actif: cfg.mcp_actif === true,
  abandons_infrastructure: abandons,
  avertissement: abandons
    ? abandons + " iteration(s) abandonnee(s) apres " + (cfg.max_tentatives||8)
      + " tentatives (statut *_abandon, erreur_infrastructure=true). A EXCLURE du"
      + " calcul des metriques et a rejouer : ce n'est pas une erreur du modele."
    : "aucune iteration perdue pour cause d'infrastructure",
  par_modele: parModele,
  fichiers_resultats: cfg.dossier_sortie + "/resultats__*.jsonl",
  suite: "uv run calculer_metriques.py \"" + cfg.dossier_sortie
         + "/resultats__*.jsonl\" --verite verite_terrain.jsonl"
}}];

const it = $('Verifier cache jeton').first().json;
const tok = $json.access_token;
if (!tok) throw new Error('Jeton non obtenu — reponse OAuth : ' + JSON.stringify($json).slice(0, 300));

// mise en cache pour les iterations suivantes
const sd = $getWorkflowStaticData('global');
sd.jeton_gcp = tok;
sd.jeton_expire_ms = Date.now() + (Number($json.expires_in || 3600) * 1000);

return [{ json: { ...it, cle: tok, jeton_en_cache: true } }];

let j = $input.first().json;
let c = null;
for (const cand of [j, j && j.data, j && j.json]) {
  if (cand && cand.refresh_token && cand.client_id) { c = cand; break; }
}
if (!c) { const b = j && (j.data || j.text);
  if (typeof b === 'string') { try { const p = JSON.parse(b); if (p.refresh_token) c = p; } catch(e){} } }
if (!c) throw new Error("Identifiants gcloud introuvables. Lancez une fois dans le terminal : gcloud auth application-default login");
return [{ json: { client_id: c.client_id, client_secret: c.client_secret, refresh_token: c.refresh_token } }];

// Le jeton OAuth gcloud vit ~1 h. L'ancien workflow en redemandait un a CHAQUE
// iteration (126 appels a oauth2.googleapis.com pour rien, et un point de panne
// sans gestion d'erreur). On le garde en cache pour la duree de la campagne.
const it = $input.first().json;
const sd = $getWorkflowStaticData('global');
const marge_ms = 5 * 60 * 1000;            // on renouvelle 5 min avant l'expiration
const valide = !!(sd.jeton_gcp && sd.jeton_expire_ms
                  && (sd.jeton_expire_ms - Date.now()) > marge_ms);
return [{ json: { ...it, cle: valide ? sd.jeton_gcp : it.cle, jeton_en_cache: valide } }];

// Backoff exponentiel avec jitter, et surtout : on ECOUTE le serveur.
// Vertex renvoie souvent un retryDelay (ex. 55s) ou un entete Retry-After ;
// l'ancien retry n8n (5 s fixes) les ignorait et relancait dans le vide.
const prep = $('Preparer l\'appel').first().json;
const cfg  = $('Configuration').first().json;
const info = $input.first().json;

const tentative = Number(info.tentative || 1) + 1;
const base    = Number(cfg.backoff_base_s || 15);
const plafond = Number(cfg.backoff_max_s || 60);

let attente = Number(info.delai_serveur_s || 0);
if (!attente || !isFinite(attente)) attente = base * Math.pow(2, tentative - 2);
attente = Math.round(attente * (1 + Math.random() * 0.3));   // jitter : desynchronise les rafales
attente = Math.max(1, Math.min(attente, plafond));           // plafond < 65 s

// on repart de l'item d'origine ; url / entetes / corps / horodatages seront
// recalcules par "Preparer l'appel", et le jeton par "Verifier cache jeton".
// L'etat de la boucle d'outils est jete avec le reste : une nouvelle
// tentative repart d'une conversation vierge, sinon le modele recevrait
// l'historique d'outils d'un appel qui a echoue.
const { url, entetes, corps, t0_ms, horodatage_debut,
        messages_etat, mcp_trace, tour, mcp_appels, mcp_ms, mcp_erreurs,
        usage_cumul, contenu_assistant, demandes_outils, corps_mcp,
        entetes_mcp, t_mcp0, ...origine } = prep;
return [{ json: { ...origine, tentative, attente_backoff_s: attente } }];

// Deplie (echantillon x run x modele) conformement a la methodologie :
// 3 executions par echantillon, une seule prediction par niveau attendue,
// zone et matrice communiquees au modele.
const config = $('Configuration').first().json;
const K = config.CLES || {};
const AGG = config.AGG_BASE || "https://api.deepinfra.com/v1/openai";

// ==== LES MODELES EVALUÉS ======== 

// Veillez mettre sur actif:true les modèles que vous souhaitez évaluer


const MODELES = [
  //Claude
  { actif:false,  fournisseur:"anthropic", modele:"claude-opus-4-8",
    base_url:"https://api.anthropic.com", cle:K.anthropic },
  { actif:false, fournisseur:"anthropic", modele:"claude-sonnet-5",
    base_url:"https://api.anthropic.com", cle:K.anthropic },

  //ChatGPT
  { actif:false, fournisseur:"openai", modele:"gpt-5.6-sol",
    base_url:"https://api.openai.com/v1", cle:K.openai },
  { actif:false, fournisseur:"openai", modele:"gpt-5.6-luna",
    base_url:"https://api.openai.com/v1", cle:K.openai },

  // GEMINI 
  //methode A (Vertex AI) : jeton gcloud injecté automatiquement
  { actif:false, fournisseur:"vertex", modele:"google/gemini-3.1-pro-preview",
    base_url:"https://aiplatform.googleapis.com/v1/projects/" + (config.gcp_project_id||"PROJET_MANQUANT") + "/locations/global/endpoints/openapi",
    cle:"(jeton gcloud injecte automatiquement a l'execution)" },
  { actif:false, fournisseur:"vertex", modele:"google/gemini-3.8-flash",
    base_url:"https://aiplatform.googleapis.com/v1/projects/" + (config.gcp_project_id||"PROJET_MANQUANT") + "/locations/global/endpoints/openapi",
    cle:"(jeton gcloud injecte automatiquement a l'execution)" },

  //methode B (cle AI Studio) : decommenter et passer A en actif:false
  // { actif:true, fournisseur:"google", modele:"gemini-3.1-pro-preview",
  //   base_url:"https://generativelanguage.googleapis.com/v1beta/openai", cle:K.google },
  //{ actif:true, fournisseur:"google", modele:"gemini-3.8-flash",
  //   base_url:"https://generativelanguage.googleapis.com/v1beta/openai", cle:K.google },


  //  // ==== OPEN-WEIGHT ====

  //Kimi
  // KIMI EN DIRECT (platform.moonshot.ai). Modeles a raisonnement :
  //  - temperature REFUSEE (400 "only 1 is allowed") -> sans_temperature:true ;
  //  - palier d'entree du compte : 3 req/min et 1 requete simultanee
  //    -> pause_apres_s: 21 (recharger le compte pour monter de palier).
  // Identifiants SANS prefixe et en minuscules ; verifier la liste vivante :
  //    GET https://api.moonshot.ai/v1/models
  //  - K3 raisonne TOUJOURS (reasoning_effort=max par defaut) et la trace de
  //    raisonnement partage le meme budget que la reponse. Le plafond commun
  //    de 32768 (noeud Configuration) lui laisse la place necessaire.
  { actif:false, fournisseur:"compat", modele:"kimi-k3",
    base_url:"https://api.moonshot.ai/v1", cle:K.kimi,
    sans_temperature:true,

    // >>>>>>>>>>>> PALIER MOONSHOT — LA SEULE LIGNE A CHANGER <<<<<<<<<<<<
    // Compte NON recharge = palier d'entree : 3 requetes/minute et 1 requete
    // simultanee. Il faut donc 21 s entre deux appels pour eviter les 429.
    pause_apres_s: 21,
    // APRES AVOIR HETE DU CREDIT : il suffit de DECOMMENTER la ligne suivante.
    // (inutile de commenter celle du dessus : en JavaScript, la derniere
    //  valeur d'une meme cle l'emporte). Campagne environ 7x plus rapide.
    // pause_apres_s: 3,
    },


  //DEEPSEEK 
  { actif:false, fournisseur:"compat", modele:"deepseek-v4-pro",
    base_url:"https://api.deepseek.com/v1", cle:K.deepseek, pause_apres_s:2 },
  { actif:false, fournisseur:"compat", modele:"deepseek-v4-flash",
    base_url:"https://api.deepseek.com/v1", cle:K.deepseek, pause_apres_s:2 },

  //QWEEN
  { actif:false, fournisseur:"compat", modele:"qwen3.8-2.4t-a95b",
    base_url:"https://dashscope-intl.aliyuncs.com/compatible-mode/v1", cle:K.qwen,
    pause_apres_s:2 },
];

const aRemplir = actifs => actifs.filter(m => /^A_REMPLIR|^COLLER_/.test(String(m.modele))
                                            || /^COLLER_/.test(String(m.cle||'')));
// Le prompt de phase 1 est repris SANS AUCUNE modification ; la consigne
// d'outils, si elle est renseignee, est ajoutee a la suite. Les deux morceaux
// sont recopies separement dans chaque enregistrement, de sorte que la seule
// difference entre les deux campagnes soit lisible dans le JSONL.
const PS_BASE = config.prompt_system;
const PS_MCP  = (config.mcp_actif === true) ? String(config.mcp_consigne || '') : '';
const PS = PS_BASE + PS_MCP;
const OUTILS_MCP = $('Normaliser les outils MCP').first().json.outils_mcp || [];
const MCP_SERVEUR = $('Normaliser les outils MCP').first().json.mcp_serveur || null;
const horodatage_campagne = new Date().toISOString();
let actifs = MODELES.filter(m => m.actif !== false);
if (config.modele_force) {
  actifs = MODELES.filter(m => m.modele === config.modele_force);
  if (!actifs.length) {
    throw new Error('MODELE_FORCE = "' + config.modele_force + '" ne correspond a aucune'
      + ' entree de MODELES. Valeurs possibles : '
      + MODELES.map(m => m.modele).join(', '));
  }
  // Garde-fou : MODELE_FORCE ignore les cases actif. Un modele force mais
  // marque actif:false est presque toujours une valeur oubliee d'une campagne
  // precedente : elle relancerait ce modele et dupliquerait ses run_id.
  if (actifs[0].actif === false) {
    throw new Error('MODELE_FORCE = "' + config.modele_force + '" vise un modele '
      + 'marque actif:false. Vider MODELE_FORCE dans Configuration (les cases '
      + 'actif:true decident), ou passer ce modele a actif:true.');
  }
}
if (!actifs.length) {
  throw new Error("Aucun modele actif : passer au moins un modele a actif:true "
    + "dans « Preparer les iterations ».");
}
const manquants = aRemplir(actifs);
if (manquants.length) {
  throw new Error("Modele(s) non configure(s) : "
    + manquants.map(m => m.modele).join(', ')
    + " — renseigner l'identifiant et la cle avant de lancer la campagne.");
}
if (config.mcp_actif === true) {
  const nonAnthropic = actifs.filter(m => m.fournisseur !== 'anthropic');
  if (nonAnthropic.length) {
    throw new Error("mcp_actif=true n'est implemente que pour l'API Messages "
      + "d'Anthropic. Modele(s) incompatible(s) : "
      + nonAnthropic.map(m => m.modele).join(', ')
      + ". Mettre mcp_actif a false, ou ne garder qu'un modele Anthropic.");
  }
  if (!OUTILS_MCP.length) {
    throw new Error("Aucun outil MCP charge : le noeud « Normaliser les outils "
      + "MCP » n'a rien renvoye alors que mcp_actif vaut true.");
  }
}
const limite = Number(config.limite_samples || 0);

// ---- 1. echantillons : un item de texte par fichier S###.jsonl ----
// zone / matrice / source sont portees par les lignes de l'echantillon : le
// pipeline n'a jamais besoin de la verite de terrain, qui reste hors de n8n-files.
const textes = $input.all().map(x => {
  const j = x.json || {};
  return j.data || j.text || j.content || j.string || '';
}).filter(t => typeof t === 'string' && t.trim());

let samples = [];
const incomplets = [];
for (const texte of textes) {
  const lignes = texte.split('\n').filter(l => l.trim());
  let log_id=null, zone=null, matrice=null, source=null;
  const logs = [];
  for (const l of lignes) {
    let o; try { o = JSON.parse(l); } catch(e) { continue; }
    if (!log_id && o.id_journal) log_id = String(o.id_journal).split('-')[0];
    if (!zone && o.zone) zone = o.zone;
    if (!matrice && o.matrice) matrice = o.matrice;
    if (!source && o.source) source = o.source;
    const c = o.contenu;
    let txt;
    if (Array.isArray(c)) txt = c.join(' | ');
    else if (c && typeof c === 'object') txt = JSON.stringify(c);
    else txt = String(c === undefined ? l : c);
    logs.push('[' + (o.source || 'log') + '] ' + txt);
  }
  if (!logs.length) continue;
  if (log_id && zone && matrice) samples.push({ log_id, zone, matrice, source: source || 'log', logs: logs.join('\n') });
  else incomplets.push(log_id || '(identifiant absent)');
}
if (incomplets.length) {
  throw new Error("Echantillon(s) sans zone/matrice/identifiant : " + incomplets.join(', ')
    + " — regenerer le corpus avec dataset/preparer_dataset.py.");
}
samples.sort((a,b) => String(a.log_id).localeCompare(String(b.log_id)));
if (limite > 0) samples = samples.slice(0, limite);
if (!samples.length) {
  throw new Error("Aucun echantillon lu depuis " + config.fichier_dataset
    + " — verifier que preparer_dataset.py a bien publie le corpus dans n8n-files.");
}

// ---- 3. deplier echantillon x run x modele ----
const LIB_ZONE = { TI: "TI (systemes d'information)", TO: "TO (systemes industriels)" };
const LIB_MATRICE = { enterprise: "MITRE ATT&CK Enterprise", ics: "MITRE ATT&CK for ICS" };
const items = [];
for (const s of samples) {
  const pu = "Zone : " + (LIB_ZONE[s.zone] || s.zone)
           + "\nMatrice a utiliser : " + (LIB_MATRICE[s.matrice] || s.matrice)
           + "\nSource de journalisation : " + s.source
           + "\n\nJournaux a analyser :\n" + s.logs;
  for (let r=0; r<config.runs_par_question; r++) {
    const numero_run = (config.numero_run_depart||1) + r;
    for (const M of actifs) {
      items.push({ json: {
        temperature: config.temperature,
        max_tokens_sortie: Number(M.max_tokens_sortie || config.max_tokens_sortie),
        timeout_appel_ms: config.timeout_appel_ms || 600000,
        version_pipeline: (config.mcp_actif === true ? (config.version_pipeline_mcp || '5.0-mcp') : config.version_pipeline), campagne: 'eval-ti-to',
        horodatage_campagne,
        // un fichier par modele : le slug neutralise les "/" et les "." des
        // identifiants (google/gemini-3.8-flash, Qwen/Qwen3.8-2.4T-A95B...)
        fichier_sortie: config.dossier_sortie + '/resultats__'
                        + M.modele.replace(/[^A-Za-z0-9._-]+/g, '_')
                        + (config.suffixe_sortie || '') + '.jsonl',
        gcp_project_id: config.gcp_project_id, mcp_actif: config.mcp_actif === true,
        mcp_url: config.mcp_url, mcp_max_tours: Number(config.mcp_max_tours || 8),
        mcp_timeout_ms: Number(config.mcp_timeout_ms || 120000),
        mcp_forcer_premier_appel: config.mcp_forcer_premier_appel === true,
        // Le bloc `tools` n'est PAS recopie dans les items : il pese 3,3 ko et
        // serait retenu par n8n pour chaque item de chaque noeud de la boucle
        // (environ 5 Mo sur une campagne de 126 iterations, en plus de
        // l'historique de conversation). Il est relu au besoin depuis le
        // noeud « Normaliser les outils MCP », qui n'a tourne qu'une fois.
        mcp_serveur: MCP_SERVEUR,
        mcp_outils_exposes: OUTILS_MCP.map(o => o.name),
        prompt_system: PS, prompt_system_base: PS_BASE, prompt_system_mcp: PS_MCP,
        prompt_user: pu,
        fournisseur: M.fournisseur, modele: M.modele, base_url: M.base_url, cle: M.cle,
        sans_temperature: M.sans_temperature === true,
        pause_apres_s: Number(M.pause_apres_s || config.pause_entre_appels_s || 1),
        log_id: s.log_id, zone: s.zone, source: s.source, matrice: s.matrice, numero_run,
        max_tentatives: config.max_tentatives || 8, tentative: 1,
        run_id: M.modele + '__' + s.log_id + '__run' + numero_run
      }});
    }
  }
}
return items;

// La sonde /healthz repond sans authentification et sans effet de bord :
// c'est le moyen le plus court de distinguer « serveur eteint » de
// « serveur demarre mais base ATT&CK incomplete ».
const cfg = $('Configuration').first().json;
if (cfg.mcp_actif !== true) return [{ json: cfg }];
const s = $input.first().json || {};
if (!s || s.status !== 'ok') {
  throw new Error("Sonde MCP muette ou anormale sur " + cfg.mcp_sonde
    + " — reponse : " + JSON.stringify(s).slice(0, 300));
}
if (s.ready !== true) {
  throw new Error("Serveur MCP demarre mais base ATT&CK incomplete (ready=false). "
    + "Lancer d'abord : uv run mcp_mitre.py --test");
}
if (cfg.mcp_version_attendue && s.version !== cfg.mcp_version_attendue) {
  throw new Error("Serveur MCP en version " + s.version + ", la campagne exige "
    + cfg.mcp_version_attendue + " (Configuration, mcp_version_attendue). Tous "
    + "les modeles compares doivent etre servis par la meme version.");
}
return [{ json: cfg }];

// Convertit tools/list (MCP) en bloc `tools` de l'API Messages d'Anthropic.
// Les deux formats partagent le meme JSON Schema : seul le nom du champ
// change (inputSchema -> input_schema). Aucune description n'est reecrite,
// pour que ce soit bien la documentation du serveur qui pilote le modele.
const cfg = $('Configuration').first().json;
if (cfg.mcp_actif !== true) {
  return [{ json: { ...cfg, outils_mcp: [], mcp_serveur: null } }];
}

const brut = $input.first().json || {};
if (brut.error !== undefined && brut.statusCode === undefined) {
  throw new Error("Serveur MCP injoignable sur " + cfg.mcp_url + " ("
    + (brut.error.message || brut.error.code || 'erreur transport') + "). "
    + "Demarrer : uv run mcp_mitre.py --http   puis verifier " + cfg.mcp_sonde
    + ". Depuis n8n en Docker, remplacer 127.0.0.1 par host.docker.internal.");
}
if (Number(brut.statusCode) !== 200) {
  throw new Error("Serveur MCP : HTTP " + brut.statusCode + " sur " + cfg.mcp_url);
}
const rep = brut.body || {};
if (rep.error) throw new Error("tools/list a echoue : " + JSON.stringify(rep.error));
const bruts = (rep.result && rep.result.tools) || [];
if (!bruts.length) throw new Error("tools/list n'a renvoye aucun outil.");

const voulus = Array.isArray(cfg.mcp_outils) ? cfg.mcp_outils : [];
const exclus = Array.isArray(cfg.mcp_outils_exclus) ? cfg.mcp_outils_exclus : [];
const dispo = bruts.map(t => t.name);
const inconnus = [...voulus, ...exclus].filter(n => !dispo.includes(n));
if (inconnus.length) {
  throw new Error("Outil(s) nomme(s) absent(s) du serveur : " + inconnus.join(', ')
    + " — outils exposes : " + dispo.join(', '));
}
// Le modele voit tout ce que le serveur publie, moins les exclusions de
// campagne. Une liste d'inclusion non vide restreint davantage : elle sert
// aux campagnes de controle, pas a la campagne de reference.
const retenus = (voulus.length ? bruts.filter(t => voulus.includes(t.name)) : bruts)
                .filter(t => !exclus.includes(t.name));
if (!retenus.length) throw new Error("Perimetre d'outils vide apres filtrage.");

const outils_mcp = retenus.map(t => ({
  name: t.name,
  description: String(t.description || '').slice(0, 4000),
  input_schema: t.inputSchema && t.inputSchema.type
    ? t.inputSchema
    : { type: 'object', properties: {}, required: [] },
}));

// Empreinte du serveur, recopiee dans chaque enregistrement : une campagne
// doit pouvoir etre rattachee a la version exacte du serveur qui l'a servie.
let mcp_serveur = null;
try {
  const s = $('Verifier le serveur MCP').first().json;
  mcp_serveur = { version: s.version, db_version: s.db_version,
                  run_id: s.run_id, ready: s.ready };
} catch (e) { mcp_serveur = null; }

return [{ json: { ...cfg, outils_mcp, mcp_serveur,
                  mcp_outils_exposes: outils_mcp.map(o => o.name),
                  mcp_tools_octets: JSON.stringify(outils_mcp).length } }];

// Etat de l'iteration en cours. "Preparer l'appel" pose le tour 1 ;
// "Integrer les resultats d'outils" pose les suivants. Le run_id departage :
// sans lui, une iteration SANS appel d'outil relirait la trace de l'iteration
// precedente, restee en memoire dans le noeud.
function noeud(nom) { try { return $(nom).first().json; } catch (e) { return null; } }
function etat() {
  const base = noeud("Preparer l'appel") || {};
  const suite = noeud("Integrer les resultats d'outils");
  return (suite && suite.run_id === base.run_id) ? suite : base;
}

// Decide s'il faut rendre la main au serveur MCP. La reponse HTTP brute est
// transmise TELLE QUELLE : "Assembler l'enregistrement" attend sa forme
// exacte (statusCode / headers / body / error).
const brut = $input.first().json || {};
const e = etat();
const panne = brut.error !== undefined && brut.statusCode === undefined;
const rep = panne ? {} : (brut.body !== undefined ? brut.body : brut);
const demande = !panne && Number(brut.statusCode) === 200
                && rep && rep.stop_reason === 'tool_use';
const tour = Number(e.tour || 1);
const max_tours = Number(e.mcp_max_tours || 8);

return [{ json: { ...brut,
  mcp_continuer: Boolean(e.mcp_actif === true && demande && tour < max_tours),
  mcp_tours_epuises: Boolean(e.mcp_actif === true && demande && tour >= max_tours),
  mcp_tour_courant: tour } }];

// Etat de l'iteration en cours. "Preparer l'appel" pose le tour 1 ;
// "Integrer les resultats d'outils" pose les suivants. Le run_id departage :
// sans lui, une iteration SANS appel d'outil relirait la trace de l'iteration
// precedente, restee en memoire dans le noeud.
function noeud(nom) { try { return $(nom).first().json; } catch (e) { return null; } }
function etat() {
  const base = noeud("Preparer l'appel") || {};
  const suite = noeud("Integrer les resultats d'outils");
  return (suite && suite.run_id === base.run_id) ? suite : base;
}

// Un tour Claude peut demander PLUSIEURS outils a la fois. Le serveur accepte
// les LOTS JSON-RPC (tableau de messages -> tableau de reponses) : les n
// appels partent donc en UNE seule requete HTTP, sans sous-boucle n8n.
const brut = $input.first().json || {};
const rep = brut.body || {};
const e = etat();
const blocs = Array.isArray(rep.content) ? rep.content : [];
const demandes = blocs.filter(b => b && b.type === 'tool_use');
if (!demandes.length) throw new Error("stop_reason=tool_use sans bloc tool_use.");

const lot = demandes.map(d => ({
  jsonrpc: "2.0", id: d.id, method: "tools/call",
  params: { name: d.name, arguments: (d.input && typeof d.input === 'object') ? d.input : {} },
}));

return [{ json: {
  ...e,
  contenu_assistant: blocs,          // recopie integrale du tour assistant
  demandes_outils: demandes.map(d => ({ id: d.id, name: d.name, input: d.input })),
  corps_mcp: JSON.stringify(lot),
  entetes_mcp: JSON.stringify({ "Content-Type": "application/json",
                                "Accept": "application/json" }),
  usage_tour: rep.usage || null,
  t_mcp0: Date.now(),
} }];

// Rend les resultats d'outils a Claude et relance le tour suivant.
// Une panne du serveur MCP n'interrompt PAS l'iteration : elle est rendue au
// modele comme un tool_result en erreur, exactement comme le ferait un client
// MCP. Le modele peut alors reformuler ou conclure sans l'outil, et la trace
// garde la panne pour l'analyse.
const lot = $('Preparer le lot MCP').first().json;
const brut = $input.first().json || {};
const ms = Date.now() - Number(lot.t_mcp0 || Date.now());

const panne = brut.error !== undefined && brut.statusCode === undefined;
let reponses = [];
let panne_txt = null;
if (panne) {
  panne_txt = 'transport - ' + String((brut.error || {}).message || brut.error).slice(0, 300);
} else if (Number(brut.statusCode) !== 200) {
  panne_txt = 'HTTP ' + brut.statusCode + ' - ' + JSON.stringify(brut.body || {}).slice(0, 300);
} else {
  const b = brut.body;
  reponses = Array.isArray(b) ? b : (b ? [b] : []);
}
const parId = {};
for (const r of reponses) if (r && r.id !== undefined) parId[String(r.id)] = r;

let nb_err = Number(lot.mcp_erreurs || 0);
const traces = [];
const resultats = lot.demandes_outils.map(d => {
  const r = parId[String(d.id)];
  let txt, err = false;
  if (panne_txt) { txt = "ERREUR serveur MCP : " + panne_txt; err = true; }
  else if (!r) { txt = "ERREUR : aucune reponse du serveur pour cet appel."; err = true; }
  else if (r.error) { txt = "ERREUR JSON-RPC " + r.error.code + " : " + r.error.message; err = true; }
  else {
    const res = r.result || {};
    const c = Array.isArray(res.content) ? res.content[0] : null;
    txt = c && typeof c.text === 'string' ? c.text : JSON.stringify(res);
    err = res.isError === true;
  }
  if (err) nb_err++;

  // Trace EXPLOITABLE pour les metriques. On ne recopie pas la reponse
  // (jusqu'a 8 ko par appel, 126 iterations), seulement ce qui permet de
  // juger l'usage des outils apres coup :
  //  - `ids`   : les identifiants ATT&CK que le serveur a effectivement
  //              renvoyes, pour verifier que le mapping final est ANCRE dans
  //              ce que le serveur a dit et non produit de memoire ;
  //  - `matrix`: la matrice demandee par le modele, ou null s'il l'a omise.
  //              Le serveur ne connait PAS la matrice prescrite par le
  //              dataset : sans ce parametre, une recherche mixe les deux
  //              matrices et peut rendre un homonyme industriel pour un
  //              comportement bureautique ;
  //  - `avert` : les garde-fous que le serveur a leves dans cette reponse.
  const ids = Array.from(new Set((txt.match(/\b(?:TA\d{4}|T\d{4}(?:\.\d{3})?)\b/g) || [])))
                   .slice(0, 60);
  const arg = (d.input && typeof d.input === 'object') ? d.input : {};
  // Un outil INEXISTANT est une hallucination d'outil : le serveur repond
  // -32602 « Outil inconnu ». calculer_metriques.py la compte a part des
  // appels en erreur, qui visent un outil reel avec de mauvais arguments.
  const inconnu = Boolean(r && r.error
                          && /outil inconnu/i.test(String(r.error.message || '')));
  // Le serveur distingue deux choses que le mot « erreur » confond :
  //  - ARGUMENTS INVALIDES (matrice inconnue, parametre mal nomme) -> isError,
  //    donc ok=false : l'appel a echoue ;
  //  - IDENTIFIANT INTROUVABLE -> reponse normale portant une cle `error`,
  //    donc ok=true : l'appel a reussi et la reponse est « n'existe pas ».
  //    C'est le signal le plus interessant du lot : le modele a soumis au
  //    serveur un identifiant qu'il avait en tete et le serveur l'a dementi.
  const introuvable = !err && /\"error\"\s*:\s*\"(Technique|Tactique|Mitigation|Groupe|Campagne|Equipement)/.test(txt);
  const avert = [];
  if (/\"homonymes\"/.test(txt)) avert.push('homonymes');
  if (/\"pivot\"/.test(txt)) avert.push('pivot');
  if (/requete d'un seul terme/.test(txt)) avert.push('requete_courte');
  if (/aucun candidat/.test(txt)) avert.push('aucun_candidat');
  if (/est revoquee/.test(txt)) avert.push('revoquee');
  if (/est DEPRECIEE/.test(txt)) avert.push('depreciee');

  // Forme attendue par calculer_metriques.py (champ racine `appels_mcp`) :
  // outil / arguments / ok / inconnu / ids_retournes. Les cles `tour`,
  // `matrix`, `avert`, `octets` et `ms` sont ADDITIVES : le script les ignore,
  // l'extension « conformite de matrice » les lit.
  traces.push({ outil: d.name, arguments: arg, ok: !err && !inconnu,
                inconnu, ids_retournes: ids, introuvable,
                tour: Number(lot.tour || 1), matrix: arg.matrix || null,
                avert, octets: txt.length, ms });
  return { type: 'tool_result', tool_use_id: d.id, content: txt, is_error: err };
});

// Conversation reconstituee : historique + tour assistant + resultats.
const messages = [...(lot.messages_etat || []),
                  { role: 'assistant', content: lot.contenu_assistant },
                  { role: 'user', content: resultats }];

const corpsObj = { model: lot.modele, max_tokens: lot.max_tokens_sortie,
                   system: lot.prompt_system, messages };
const outils = $('Normaliser les outils MCP').first().json.outils_mcp || [];
if (outils.length) {
  corpsObj.tools = outils;
  // Des le deuxieme tour, `auto` : le modele a deja consulte le referentiel,
  // il doit pouvoir conclure. Rester en `any` le forcerait a boucler jusqu'a
  // epuisement du budget de tours.
  corpsObj.tool_choice = { type: 'auto' };
}

const u = lot.usage_tour || {};
return [{ json: { ...lot,
  corps: JSON.stringify(corpsObj),
  messages_etat: messages,
  tour: Number(lot.tour || 1) + 1,
  mcp_trace: [...(lot.mcp_trace || []), ...traces],
  mcp_appels: Number(lot.mcp_appels || 0) + resultats.length,
  mcp_ms: Number(lot.mcp_ms || 0) + ms,
  mcp_erreurs: nb_err,
  usage_cumul: { entree: Number((lot.usage_cumul||{}).entree || 0) + Number(u.input_tokens || 0),
                 sortie: Number((lot.usage_cumul||{}).sortie || 0) + Number(u.output_tokens || 0) },
  contenu_assistant: undefined, demandes_outils: undefined,
  corps_mcp: undefined, entetes_mcp: undefined, t_mcp0: undefined } }];
